import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"文公易說","description":"文公易說 - 文公易說","frontmatter":{"title":"文公易說","description":"文公易說 - 文公易說"},"headers":[],"relativePath":"classics/wengong-zhu/001.md","filePath":"classics/wengong-zhu/001.md"}'),l={name:"classics/wengong-zhu/001.md"};function o(c,a,i,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"文公易說",tabindex:"-1"},[r("文公易說 "),e("a",{class:"header-anchor",href:"#文公易說","aria-label":"Permalink to “文公易說”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：朱文公易說二十二卷，宋朱鑑編。案朱子世系，朱子三子，長曰塾。塾二子，長曰鑑，則朱子嫡長孫也。鑑字子明，以蔭補迪功郎，官至湖廣總領。朱子注易之書，為目有五：曰易傳十一卷，曰易本義十二卷，曰易學啟蒙三卷，曰古易音訓二卷，曰蓍卦考誤。一巷皆有成帙。其朋友論難與及門之辨說，則散見語錄中。鑑匯而葺之，以成是編。昔鄭元箋註諸經，其孫魏侍中小同復裒其門人問答之詞，為鄭志十一巷。鑑之編輯緒言，亦猶此例也。考朱子初作易傳，用王弼本，後作易本義，始用呂祖謙本。易傳，宋志著錄，今已散佚。當理宗以後，朱子之學大行，剩語殘編，無不奉為球璧，不應手成巨帙，反至無傳。殆以未定之說，自削其稿，故不復流佈與？鑑是書全採語錄之文，以補本義之闕。其中或門人記述，未必盡合師說，或偶然問答，未必勒為確論。安知無如易傳之類，為朱子所欲刊除者？然收拾放佚，以備考證，亦可雲能世其家學矣。乾隆四十二年二月恭校上。",-1),e("p",null,"總纂官 臣 紀呁、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。",-1)])])}const f=t(l,[["render",o]]);export{_ as __pageData,f as default};
